package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class CreditCheckIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_to_a_blocked_member_returns_409_with_credit_rejected_error() throws Exception {
        String blockedMemberId = registerMember("BLOCKED-kim");

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(registerBook(), blockedMemberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("CREDIT_REJECTED"));
    }

    @Test
    void book_stays_loanable_after_a_credit_rejection() throws Exception {
        String bookId = registerBook();
        String blockedMemberId = registerMember("BLOCKED-kim");
        String normalMemberId = registerMember("이순신");

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, blockedMemberId)))
                .andExpect(status().isConflict());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, normalMemberId)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.bookId").value(bookId));
    }

    @Test
    void rejected_loan_does_not_consume_the_members_loan_slots_or_leave_a_record() throws Exception {
        String blockedMemberId = registerMember("BLOCKED-kim");
        String bookId = registerBook();

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, blockedMemberId)))
                .andExpect(status().isConflict());

        mockMvc.perform(get("/members/{memberId}/loans", blockedMemberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalCount").value(0));
    }

    @Test
    void get_loan_returns_the_credit_check_saved_with_the_loan() throws Exception {
        String memberId = registerMember("이순신");
        LocalDate loanedAt = LocalDate.of(2026, 3, 2);
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBodyOn(registerBook(), memberId, loanedAt)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        String loanId = objectMapper.readTree(loaned).get("loanId").asText();

        mockMvc.perform(get("/loans/{loanId}", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.memberId").value(memberId))
                .andExpect(jsonPath("$.loanedAt").value("2026-03-02"))
                .andExpect(jsonPath("$.dueAt").value("2026-03-16"))
                .andExpect(jsonPath("$.creditCheck.approved").value(true))
                .andExpect(jsonPath("$.creditCheck.score").value(742))
                .andExpect(jsonPath("$.creditCheck.checkedAt").isNotEmpty());
    }

    @Test
    void get_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(get("/loans/{loanId}", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String registerMember(String name) throws Exception {
        String body = objectMapper.writeValueAsString(new MemberBody(name));
        String response = mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode node = objectMapper.readTree(response);
        return node.get("memberId").asText();
    }

    private String registerBook() throws Exception {
        String response = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("id").asText();
    }

    private String loanBody(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId));
    }

    private String loanBodyOn(String bookId, String memberId, LocalDate loanedAt) throws Exception {
        return objectMapper.writeValueAsString(new LoanBodyOn(bookId, memberId, loanedAt));
    }

    private record MemberBody(String name) {
    }

    private record LoanBody(String bookId, String memberId) {
    }

    private record LoanBodyOn(String bookId, String memberId, LocalDate loanedAt) {
    }
}
